	RemoveTextAfterFocusLost = false,
	Callback = function(Text)
        if Text=="0" or not tonumber(Text) then
            disabled=true
        else
            disabled=true
            wait(.1)
            disabled=false
            while disabled~=true do
            	task.wait(tonumber(Text))
                task.spawn(function()
