function getInfoSword(SwordName)
    if game.Players.LocalPlayer.Character:FindFirstChild(SwordName) then
        return true;
    elseif game.Players.LocalPlayer.Backpack:FindFirstChild(SwordName) then
        return true;
    end
    return false;
end
