local function IsPlayerOwned(part)
    local iter, state, index = ipairs(Services.Players:GetPlayers())
    while true do
        local player
        index, player = iter(state, index)
        if index == nil then
            break
        end
        if player.Character and part:IsDescendantOf(player.Character) then
            return true
        end
    end
    return false
