                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    if hum and hrp and hum.MoveDirection.Magnitude > 0 then 
                        pcall(function() 
                            hrp.CFrame = hrp.CFrame + (hum.MoveDirection * (tpSpeedValue - 16) * 0.05) 
                        end) 
                    end
                    RunService.RenderStepped:Wait()
                end
            end) 
        end
    end 
})

