local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")
local Players = game:GetService("Players")

local Player = Players.LocalPlayer
local Event = ReplicatedStorage:WaitForChild("Packages"):WaitForChild("_Index")["rajden28_packet@1.7.3"].packet.RemoteEvent

local BOSS_NAME = "workspace.Temps.Boss"
local MINION_NAMES = {
    "Puffer", "MantaRay", "Lumionix", "JellyFish", 
    "RedCrad", "OrangeSquid", "Dolphin", "ClownFish", "ButterflyFish", "BlueLobster"
}

local rawData = "\x02\xFE\x18\x8C\xC2\x96@\b\xC3\xF1\x13\x83B"
local buf = buffer.fromstring(rawData)

local _G_AutoAttack = false

local function GetPriorityTarget()
    local character = Player.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if not root then return nil end
    
    local myPos = root.Position
    local children = Workspace:GetChildren()

    local bestBoss = nil
    local bossShortestDist = math.huge
    local bestMinion = nil
    local minionShortestDist = math.huge

    for _, obj in ipairs(children) do
        if obj.Name == BOSS_NAME then
            local success, pos = pcall(function() return obj:GetPivot().Position end)
            if success then
                local dist = (myPos - pos).Magnitude
                if dist < bossShortestDist then
                    bossShortestDist = dist
                    bestBoss = {Instance = obj, Position = pos}
                end
            end
        else
            local isMinion = false
            for _, mName in ipairs(MINION_NAMES) do
                if obj.Name == mName then
                    isMinion = true
                    break
                end
            end

            if isMinion then
                local success, pos = pcall(function() return obj:GetPivot().Position end)
                if success then
                    local dist = (myPos - pos).Magnitude
                    if dist < minionShortestDist then
                        minionShortestDist = dist
                        bestMinion = {Instance = obj, Position = pos}
                    end
                end
            end
        end
    end

    return bestBoss or bestMinion
end

task.spawn(function()
    while true do
        if _G_AutoAttack then
            local targetData = GetPriorityTarget()
            if targetData then
                local pos = targetData.Position
                buffer.writef32(buf, 1, pos.X)
                buffer.writef32(buf, 5, pos.Y)
                buffer.writef32(buf, 9, pos.Z)
                Event:FireServer(buf)
            end
        end
        task.wait(0.01)
    end
end)

