        local sellEvent = game:GetService("ReplicatedStorage").Packages._Index["rajden28_packet@1.7.3"].packet.RemoteEvent
        sellEvent:FireServer(buffer.fromstring("\x11\x11\aSellAll"))
    end
})]=] 
