    Icon = Color3.fromHex("#a1a1aa"),
})

local Window = WindUI:CreateWindow({
    Title = "Aero      ",
    Folder = "Aero",
    SideBarWidth = 180,
    Background = "https://chaton-images.s3.us-east-2.amazonaws.com/GHn9L9UJLf0XcVNyCpbG72D0rmNmBEWndPkh6CjJNya8GLnWzz1vImvt8wlJSBwv_2700x1519x1393696.jpeg", -- video 
    BackgroundImageTransparency = 0.5,
    OpenButton = {
        Title = "打开脚本",
        CornerRadius = UDim.new(1, 0),
        StrokeThickness = 3,
        Enabled = true,
        Draggable = true,
        OnlyMobile = false,
        Scale = 0.9,
        Color = ColorSequence.new(
            Color3.fromHex("#30FF6A"),
            Color3.fromHex("#e7ff2f")
        ),
    },
    Topbar = {
        Height = 44,
        ButtonsType = "Mac",
    },
})

Window:Tag({ Title = "V1.03", Color = Color3.fromHex("00CED1"), Radius = 2 })
Window:Tag({ Title = "伊散", Icon = "crown", Color = Color3.fromHex("FFD700"), Radius = 2 })
Window:Tag({ Title = "苏达", Icon = "square-chevron-right", Color = Color3.fromHex("#30ff6a"), Radius = 2 })

-- ==================== 服务与变量 ====================
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local Lighting = game:GetService("Lighting")
local TweenService = game:GetService("TweenService")
local LocalPlayer = Players.LocalPlayer

-- 原有变量
local CombatEnabled = false 
local targetCount = 1      
local WalkSpeedValue = 16

-- 绕圈跟随变量
local RandomFollowEnabled = false
local currentTarget = nil
local followDistance = 4  -- 绕圈的半径（距离）
local orbitSpeed = 20     -- 绕圈的速度（数值越大转得越快）

-- ==================== 功能函数 ====================
local function getAllNilInstances(name, class)
    local found = {}
    if getnilinstances then
        for _, v in next, getnilinstances() do
            if v.Name == name and (not class or v.ClassName == class) then
                table.insert(found, v)
            end
        end
    end
    return found
end

local function getNearestPlayers(count)
    local targetList = {}
    local lChar = LocalPlayer.Character
    local lRoot = lChar and lChar:FindFirstChild("HumanoidRootPart")
    if not lRoot then return targetList end

    local playersWithDist = {}
    for _, player in pairs(Players:GetPlayers()) do
        if player ~= LocalPlayer and player.Character then
            local root = player.Character:FindFirstChild("HumanoidRootPart")
            if root then
                local distance = (lRoot.Position - root.Position).Magnitude
                table.insert(playersWithDist, {player = player, dist = distance, root = root})
            end
        end
    end
    table.sort(playersWithDist, function(a, b) return a.dist < b.dist end)
    for i = 1, math.min(count, #playersWithDist) do
        table.insert(targetList, playersWithDist[i])
    end
    return targetList
end

-- 随机获取一个玩家的函数 (排除自己)
local function getRandomPlayer()
    local allPlayers = Players:GetPlayers()
    local eligiblePlayers = {}
    for _, p in pairs(allPlayers) do
        if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
            table.insert(eligiblePlayers, p)
        end
    end
    if #eligiblePlayers > 0 then
        return eligiblePlayers[math.random(1, #eligiblePlayers)]
    else
        return nil
    end
end

-- ==================== UI 菜单 ====================
local Tab = Window:Tab({
    Title = "主要功能",
    Icon = "sparkles",
})
Window:SelectTab(1)

Tab:Toggle({
    Title = "杀戮光环",
    Value = false,
    Callback = function(state)
        CombatEnabled = state
    end
})

-- 名称改为绕圈跟随
Tab:Toggle({
    Title = "传送全部人",
    Value = false,
    Callback = function(state)
        RandomFollowEnabled = state
        if not state then
            currentTarget = nil -- 关闭时清空目标
        end
    end
})

Tab:Button({
    Title = "删除教学楼大门",
    Callback = function()
        local school = workspace:FindFirstChild("\229\173\166\230\160\161")
        local building = school and school:FindFirstChild("\230\149\153\229\173\166\230\165\188")
        local door = building and building:FindFirstChild("\230\149\153\229\173\166\230\165\188\229\164\167\233\151\168")
        if door then door:Destroy() end
    end
})

Tab:Button({
    Title = "删除二号小门",
    Callback = function()
        local school = workspace:FindFirstChild("\229\173\166\230\160\161")
        local exitGate = school and school:FindFirstChild("\229\135\186\229\133\165\229\143\163\229\164\167\233\151\168")
        local smallGate = exitGate and exitGate:FindFirstChild("\228\186\140\229\143\183\229\176\143\233\151\168")
        if smallGate then smallGate:Destroy() end
    end
})

-- ==================== 后台逻辑 ====================

-- 1. 原有的：移速与杀戮光环循环
task.spawn(function()
    while true do
        task.wait(0.3)
        local char = LocalPlayer.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if hum and hum.WalkSpeed ~= WalkSpeedValue then
            hum.WalkSpeed = WalkSpeedValue
        end

        if CombatEnabled then
            if hum then
                local equippedTool = char:FindFirstChildOfClass("Tool")
                if not equippedTool then
                    local backpack = LocalPlayer:FindFirstChild("Backpack")
                    local firstTool = backpack and backpack:FindFirstChildOfClass("Tool")
                    if firstTool then
                        hum:EquipTool(firstTool)
                    end
                end
            end

            local targets = getNearestPlayers(targetCount)
            local nilParts = getAllNilInstances("Part", "Part") 
            if #targets > 0 then
                local character = LocalPlayer.Character
                local fist = character and character:FindFirstChild("\230\139\179\229\164\180") or character:FindFirstChildOfClass("Tool")
                
                for i, part in ipairs(nilParts) do
                    local targetData = targets[(i % #targets) + 1]
                    if targetData and targetData.root then
                        if part:IsA("BasePart") then
                            part.CFrame = targetData.root.CFrame
                        elseif part:IsA("Model") then
                            part:SetPrimaryPartCFrame(targetData.root.CFrame)
                        end
                    end
                end
                
                if fist and fist:FindFirstChild("Attack") then
                    for _, targetData in ipairs(targets) do
                        fist.Attack:FireServer(targetData.player)
                    end
                end
            end
        end
    end
end)

-- 2. 穿墙逻辑 (仅在开启跟随开关时生效)
RunService.Stepped:Connect(function()
    if RandomFollowEnabled and LocalPlayer.Character then
        for _, part in pairs(LocalPlayer.Character:GetDescendants()) do
            if part:IsA("BasePart") then
                part.CanCollide = false
            end
        end
    end
end)

-- 3. 每四秒切换一次目标的循环
task.spawn(function()
    while true do
        if RandomFollowEnabled then
            local nextPlayer = getRandomPlayer()
            if nextPlayer then
                currentTarget = nextPlayer
            end
            task.wait(4) -- 每4秒切换一次
        else
            task.wait(0.5) -- 没开启时降低循环频率节省性能
        end
    end
end)

-- ==================== 视觉效果与高频更新 ====================

local gradient = nil

RunService.Heartbeat:Connect(function()
    -- 绕圈跟随的坐标计算逻辑
    if RandomFollowEnabled and currentTarget and currentTarget.Character then
        local targetRoot = currentTarget.Character:FindFirstChild("HumanoidRootPart")
        local myCharacter = LocalPlayer.Character
        local myRoot = myCharacter and myCharacter:FindFirstChild("HumanoidRootPart")

        if targetRoot and myRoot then
            -- 获取运行时间以计算旋转角度
            local t = tick() * orbitSpeed 
            
            -- 使用三角函数计算 X 和 Z 轴的偏移量
            local offsetX = math.cos(t) * followDistance
            local offsetZ = math.sin(t) * followDistance
            
            -- 计算绕圈位置 (目标位置 + 偏移量)
            local orbitPosition = targetRoot.Position + Vector3.new(offsetX, 0, offsetZ)
            
            -- 强制设置位置，并让角色始终面朝目标 (LookAt)
            myRoot.CFrame = CFrame.new(orbitPosition, targetRoot.Position)
        end
    end

    -- 彩虹边框动画
    if gradient then 
        gradient.Rotation = (tick() * 50) % 360 
    end
end)

-- UI 打开时的模糊效果
local blur = Lighting:FindFirstChildOfClass("BlurEffect") or Instance.new("BlurEffect", Lighting)
task.spawn(function()
    local wasOpen = false
    while true do
        task.wait(0.1)
        local mainFrame = Window.UIElements and Window.UIElements.Main
        local isOpen = mainFrame and mainFrame.Visible or false
        if isOpen ~= wasOpen then
            wasOpen = isOpen
            TweenService:Create(blur, TweenInfo.new(0.3), {Size = isOpen and 20 or 0}):Play()
        end
    end
end)

-- 创建彩虹边框
local function createRainbowBorder(window)
    local mainFrame = window.UIElements.Main
    if not mainFrame then return end
    local rainbowStroke = mainFrame:FindFirstChild("RainbowStroke") or Instance.new("UIStroke")
    rainbowStroke.Name = "RainbowStroke"
    rainbowStroke.Thickness = 2
    rainbowStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    rainbowStroke.Parent = mainFrame
    local glowEffect = rainbowStroke:FindFirstChild("GlowEffect") or Instance.new("UIGradient")
    glowEffect.Name = "GlowEffect"
    glowEffect.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromHex("FF0000")),
        ColorSequenceKeypoint.new(0.5, Color3.fromHex("00FF00")),
        ColorSequenceKeypoint.new(1, Color3.fromHex("0000FF"))
    })
    glowEffect.Parent = rainbowStroke
    return glowEffect
end

gradient = createRainbowBorder(Window)]=] 
 AeroScripts['战争机器'] = [=[local VirtualInputManager = game:GetService('VirtualInputManager')
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local Lighting = game:GetService("Lighting")

getgenv().WarMachinesExecuted = false
getgenv().TweenTeleportTakenTime = 0.5
getgenv().Return = false
getgenv().AutoCooldown = true

local WindUI = loadstring(game:HttpGet("https://raw.githubusercontent.com/Yisan886/Aero/refs/heads/main/ui.lua.txt"))()

WindUI:AddTheme({
    Name = "My Theme",
    Accent = Color3.fromHex("#18181b"),
    Background = Color3.fromHex("#101010"),
    Outline = Color3.fromHex("#FFFFFF"),
    Text = Color3.fromHex("#FFFFFF"),
    Placeholder = Color3.fromHex("#7a7a7a"),
    Button = Color3.fromHex("#52525b"),
    Icon = Color3.fromHex("#a1a1aa"),
})

local Window = WindUI:CreateWindow({
    Title = "Aero      ",
    Folder = "Aero",
    SideBarWidth = 180,
    Background = "https://chaton-images.s3.us-east-2.amazonaws.com/GHn9L9UJLf0XcVNyCpbG72D0rmNmBEWndPkh6CjJNya8GLnWzz1vImvt8wlJSBwv_2700x1519x1393696.jpeg", -- video 
    BackgroundImageTransparency = 0.5,
    OpenButton = {
        Title = "打开脚本",
        CornerRadius = UDim.new(1, 0),
        StrokeThickness = 3,
        Enabled = true,
        Draggable = true,
        OnlyMobile = false,
        Scale = 0.9,
        Color = ColorSequence.new(
            Color3.fromHex("#30FF6A"),
            Color3.fromHex("#e7ff2f")
        ),
    },
    Topbar = {
        Height = 44,
        ButtonsType = "Mac",
    },
})

Window:Tag({
    Title = "V1.03",
    Color = Color3.fromHex("00CED1"),
    Radius = 2,
})

Window:Tag({
    Title = "伊散",
    Icon = "crown",
    Color = Color3.fromHex("FFD700"),
    Radius = 2,
})

Window:Tag({
    Title = "苏达",
    Icon = "square-chevron-right",
    Color = Color3.fromHex("#30ff6a"),
    Radius = 2,
})

local COLOR_SCHEMES = {
    ["彩虹颜色"] = {ColorSequence.new({
        ColorSequenceKeypoint.new(0,    Color3.fromHex("FF0000")),
        ColorSequenceKeypoint.new(0.16, Color3.fromHex("FFA500")),
        ColorSequenceKeypoint.new(0.33, Color3.fromHex("FFFF00")),
        ColorSequenceKeypoint.new(0.5,  Color3.fromHex("00FF00")),
        ColorSequenceKeypoint.new(0.66, Color3.fromHex("0000FF")),
        ColorSequenceKeypoint.new(0.83, Color3.fromHex("4B0082")),
        ColorSequenceKeypoint.new(1,    Color3.fromHex("EE82EE"))
    }), "palette"},

    ["绿黄渐变"] = {ColorSequence.new({
        ColorSequenceKeypoint.new(0,   Color3.fromHex("30FF6A")),
        ColorSequenceKeypoint.new(0.5, Color3.fromHex("a8ff00")),
        ColorSequenceKeypoint.new(1,   Color3.fromHex("e7ff2f"))
    }), "waves"},
}

local borderAnimation
local animationSpeed = 5

local function createRainbowBorder(window, colorScheme)
    local mainFrame = window.UIElements.Main
    if not mainFrame then return nil end

    local existingStroke = mainFrame:FindFirstChild("RainbowStroke")
    if existingStroke then existingStroke:Destroy() end

    if not mainFrame:FindFirstChildOfClass("UICorner") then
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 16)
        corner.Parent = mainFrame
    end

    local rainbowStroke = Instance.new("UIStroke")
    rainbowStroke.Name = "RainbowStroke"
    rainbowStroke.Thickness = 2
    rainbowStroke.Color = Color3.new(1, 1, 1)
    rainbowStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    rainbowStroke.LineJoinMode = Enum.LineJoinMode.Round
    rainbowStroke.Parent = mainFrame

    local glowEffect = Instance.new("UIGradient")
    glowEffect.Name = "GlowEffect"
    local schemeData = COLOR_SCHEMES[colorScheme or "彩虹颜色"]
    glowEffect.Color = schemeData and schemeData[1] or COLOR_SCHEMES["彩虹颜色"][1]
    glowEffect.Rotation = 0
    glowEffect.Parent = rainbowStroke

    return rainbowStroke
end

local function startBorderAnimation(window, speed)
    local mainFrame = window.UIElements.Main
    if not mainFrame then return nil end
    local rainbowStroke = mainFrame:FindFirstChild("RainbowStroke")
    if not rainbowStroke then return nil end
    local glowEffect = rainbowStroke:FindFirstChild("GlowEffect")
    if not glowEffect then return nil end

    return game:GetService("RunService").Heartbeat:Connect(function()
        if not rainbowStroke or rainbowStroke.Parent == nil then return end
        glowEffect.Rotation = (tick() * speed * 10) % 360
    end)
end

local rainbowStroke = createRainbowBorder(Window, "彩虹颜色")
if rainbowStroke then
    borderAnimation = startBorderAnimation(Window, animationSpeed)
end

local Lighting = game:GetService("Lighting")
local TweenServiceBlur = game:GetService("TweenService")

local blur = Lighting:FindFirstChildOfClass("BlurEffect")
if not blur then
    blur = Instance.new("BlurEffect")
    blur.Size = 0
    blur.Parent = Lighting
end

task.spawn(function()
    local wasOpen = false
    while true do
        task.wait(0.1)
        local mainFrame = Window.UIElements and Window.UIElements.Main
        local isOpen = mainFrame and mainFrame.Visible or false
        
        if isOpen ~= wasOpen then
            wasOpen = isOpen
            TweenServiceBlur:Create(blur, TweenInfo.new(0.3), {
                Size = isOpen and 20 or 0
            }):Play()
        end
    end
end)
local Tab = Window:Tab({
    Title = "功能",
    Icon = "sparkles",
})
Window:SelectTab(1)
Tab:Toggle({
    Title = "自动刷钱",
    Desc = "需要变身钢铁侠",
    Value = false,
    Callback = function(state)
        getgenv().WarMachinesExecuted = state
        
        if state then
            task.spawn(function()
                local player = game.Players.LocalPlayer
                local character = player.Character or player.CharacterAdded:Wait()
                local hrp = character:WaitForChild("HumanoidRootPart")

                hrp.CFrame = CFrame.new(500, 700, 265)
                task.wait(0.1)
                
                for i = 1, 2 do
                    VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
                    task.wait(0.1)
                    VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
                    task.wait(0.1)
                end
                
                VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.LeftShift, false, game)
                task.wait(0.0001)
                VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.LeftShift, false, game)

                if getgenv().PlrVelocity then getgenv().PlrVelocity:Destroy() end
                getgenv().PlrVelocity = Instance.new("BodyVelocity")
                getgenv().PlrVelocity.Parent = character:WaitForChild("LowerTorso")
                getgenv().PlrVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)

                local Loops = 0
                local Direction = 1

                while getgenv().WarMachinesExecuted do
                    Loops = Loops + 1
                    if Loops == 40 and getgenv().Return == true then
                        Direction = Direction * -1
                        Loops = 0
                    else
                        getgenv().PlrVelocity.Velocity = Vector3.new(0, 1250 * Direction, 0)
                        task.wait(0.5)
                    end
                    
                    getgenv().PlrVelocity.Velocity = Vector3.new(0, 100, 0)

                    if character:GetAttribute("Overheat") ~= nil then
                        if getgenv().AutoCooldown and character:GetAttribute("Overheat") >= 900 then
                            repeat
                                hrp.CFrame = CFrame.new(-830.82, 285, -509.22)
                                VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
                                task.wait(0.1)
                                VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
                                task.wait(0.1)
                                if not getgenv().WarMachinesExecuted then break end
                            until character:GetAttribute("Overheat") <= 50 or not getgenv().WarMachinesExecuted
                        end
                    end

                    if player.PlayerGui.Client.SideBar.Visible and player.PlayerGui.Hotbar.Enabled then
                        VirtualInputManager:SendKeyEvent(true, Enum.KeyCode.Space, false, game)
                        task.wait(0.1)
                        VirtualInputManager:SendKeyEvent(false, Enum.KeyCode.Space, false, game)
                        task.wait(0.1)
                    end
                    task.wait(0.01)
                end
            end)
        else
            if getgenv().PlrVelocity then
                getgenv().PlrVelocity.Velocity = Vector3.new(0,0,0)
                local hrp = game.Players.LocalPlayer.Character.HumanoidRootPart
                TweenService:Create(hrp, TweenInfo.new(getgenv().TweenTeleportTakenTime), {CFrame = CFrame.new(500, 700, 265)}):Play()
                task.wait(getgenv().TweenTeleportTakenTime)
                getgenv().PlrVelocity:Destroy()
                getgenv().PlrVelocity = nil
                hrp.Velocity = Vector3.new(0,-10,0)
                task.wait(.25)
                hrp.CFrame = CFrame.new(500, 640, 265)
            end
        end
    end
})]=] 
