local function StartFarm()
    if not serviceNpcsFolder or not questAcceptRemote then return end
    StopFarm()
    farmThread = task.spawn(function()
        while Config.Enabled do
            local questInfo = QuestMap[Config.SelectedQuest]
            if not questInfo then task.wait(1) end
            questCompleted = false
            questKills = 0
            questRequired = questInfo.amount
            local npcObj = serviceNpcsFolder:FindFirstChild(questInfo.npc)
            if not npcObj then
                WindUI:Notify({Title = "错误", Content = "未找到NPC: " .. questInfo.npc, Duration = 3})
                task.wait(2)
            end
            TeleportToNPC(npcObj)
            task.wait(0.5)
            questAcceptRemote:FireServer(questInfo.npc)
            task.wait(0.5)
            WindUI:Notify({Title = Config.SelectedQuest, Content = "已接受!", Duration = 2})
            while Config.Enabled do
                if questCompleted then
                    WindUI:Notify({Title = Config.SelectedQuest, Content = "已完成! 重新接取...", Duration = 2})
                    task.wait(1)
                    break
                end
                local mob, primary = FindClosestMob(questInfo.mobType, questInfo.specificMobs)
                if mob and primary then
                    AttackMob(mob, primary)
                    RunService.Heartbeat:Wait()
                else
                    task.wait(0.3)
                end
            end
        end
    end)
end

local function StartAutoFarm()
    StopAutoFarm()
    autoFarmThread = task.spawn(function()
        local farmInfo = nil
        for _, info in ipairs(FarmMobs) do
            if info.name == Config.SelectedFarmMob then farmInfo = info break end
        end
        if not farmInfo then return end
        while Config.FarmEnabled do
            local mob, primary = FindClosestFarmMob(farmInfo.mobs)
            if mob and primary then
                AttackMob(mob, primary)
                RunService.Heartbeat:Wait()
            else
                task.wait(0.5)
            end
        end
    end)
end

local function StartBossFarm()
    StopBossFarm()
    bossFarmThread = task.spawn(function()
        local bossInfo = nil
        for _, info in ipairs(BossMobs) do
            if info.name == Config.SelectedBoss then bossInfo = info break end
        end
        if not bossInfo then return end
        while Config.BossFarmEnabled do
            local mob, primary = FindClosestFarmMob(bossInfo.mobs)
            if mob and primary then
                local pos = primary.Position
                local hrp = GetHRP()
                if hrp then
                    hrp.CFrame = CFrame.lookAt(pos + Vector3.new(0, Config.BossAttackHeight, 0), pos)
                    hrp.AssemblyLinearVelocity = Vector3.zero
                    if requestHitRemote then requestHitRemote:FireServer(mob) end
                end
                RunService.Heartbeat:Wait()
            else
                task.wait(0.5)
            end
        end
    end)
end

local function StartAutoChest()
    if not useItemRemote then return end
    StopAutoChest()
    autoChestThread = task.spawn(function()
        local totalOpened = 0
        while Config.ChestEnabled do
            useItemRemote:FireServer("Use", Config.SelectedChest, Config.ChestBatch, false)
            totalOpened = totalOpened + Config.ChestBatch
            if Config.ChestAmountEnabled and totalOpened >= Config.ChestAmount then
                Config.ChestEnabled = false
                WindUI:Notify({Title = "宝箱", Content = "已完成开启 " .. Config.ChestAmount .. " 个宝箱", Duration = 3})
                break
            end
            task.wait(Config.ChestSpeed)
        end
    end)
end

local function StartAbilityZ()
    if abilityZThread then task.cancel(abilityZThread) end
    abilityZThread = task.spawn(function()
        while Config.AbilityZEnabled do if requestAbilityRemote then requestAbilityRemote:FireServer(1) end task.wait(Config.AbilityZCooldown) end
    end)
end
local function StartAbilityX()
    if abilityXThread then task.cancel(abilityXThread) end
    abilityXThread = task.spawn(function()
        while Config.AbilityXEnabled do if requestAbilityRemote then requestAbilityRemote:FireServer(2) end task.wait(Config.AbilityXCooldown) end
    end)
end
local function StartAbilityC()
    if abilityCThread then task.cancel(abilityCThread) end
    abilityCThread = task.spawn(function()
        while Config.AbilityCEnabled do if requestAbilityRemote then requestAbilityRemote:FireServer(3) end task.wait(Config.AbilityCCooldown) end
    end)
end
local function StartAbilityV()
    if abilityVThread then task.cancel(abilityVThread) end
    abilityVThread = task.spawn(function()
        while Config.AbilityVEnabled do if requestAbilityRemote then requestAbilityRemote:FireServer(4) end task.wait(Config.AbilityVCooldown) end
    end)
end

local function StartStatMelee()
    if statMeleeThread then task.cancel(statMeleeThread) end
    statMeleeThread = task.spawn(function()
        local allocated = 0
        while Config.StatMeleeEnabled and allocateStatRemote do
            allocateStatRemote:FireServer("Melee", Config.StatMeleeBatch)
            allocated = allocated + Config.StatMeleeBatch
            if Config.StatMeleeAmountEnabled and allocated >= Config.StatMeleeAmount then
                Config.StatMeleeEnabled = false
                WindUI:Notify({Title = "Melee", Content = "点数分配完成", Duration = 3})
                break
            end
            task.wait(Config.StatMeleeSpeed)
        end
    end)
end
