local UISection = UITab:Section({ Title = "菜单设置" })
UISection:Button({
    Title = "卸载脚本",
    Icon = "trash-2",
    Callback = function()
        Config.Enabled = false Config.FarmEnabled = false Config.BossFarmEnabled = false
        Config.ChestEnabled = false Config.AbilityZEnabled = false Config.AbilityXEnabled = false
        Config.AbilityCEnabled = false Config.AbilityVEnabled = false
        Config.StatMeleeEnabled = false Config.StatDefenseEnabled = false
        Config.StatSwordEnabled = false Config.StatPowerEnabled = false
        Config.KillAuraEnabled = false Config.AutoHakiEnabled = false
        Config.AutoTimedBossEnabled = false Config.AutoStatsEnabled = false
        for i = 1, 4 do
            if slots[i] then slots[i].enabled = false end
            if slotThreads[i] then task.cancel(slotThreads[i]) end
        end
        StopFarm() StopAutoFarm() StopBossFarm() StopAutoChest() StopAutoAbilities() StopAutoStats()
        StopKillAura() StopAutoHaki() StopAutoTimedBoss() StopAutoStatsAll()
        if Window and Window.Destroy then Window:Destroy() end
    end
})

Window:OnDestroy(function()
    windowOpen = false
    Config.Enabled = false Config.FarmEnabled = false Config.BossFarmEnabled = false
    Config.ChestEnabled = false Config.AbilityZEnabled = false Config.AbilityXEnabled = false
    Config.AbilityCEnabled = false Config.AbilityVEnabled = false
    Config.StatMeleeEnabled = false Config.StatDefenseEnabled = false
    Config.StatSwordEnabled = false Config.StatPowerEnabled = false
    Config.KillAuraEnabled = false Config.AutoHakiEnabled = false
    Config.AutoTimedBossEnabled = false Config.AutoStatsEnabled = false
    for i = 1, 4 do
        if slots[i] then slots[i].enabled = false end
        if slotThreads[i] then task.cancel(slotThreads[i]) end
    end
    StopFarm() StopAutoFarm() StopBossFarm() StopAutoChest() StopAutoAbilities() StopAutoStats()
    StopKillAura() StopAutoHaki() StopAutoTimedBoss() StopAutoStatsAll()
    if borderAnimation then borderAnimation:Disconnect() borderAnimation = nil end
