    Value = false,
    Callback = function(state) 
        KillAllEnabled = state
        
            if KillAllEnabled then
            task.spawn(function()
                while KillAllEnabled do
                    pcall(function()
                        local char = LocalPlayer.Character
                        if not char then return end
                        
                        local tool = char:FindFirstChildOfClass("Tool")
                        if not tool then
                            local backpackTool = LocalPlayer.Backpack:FindFirstChildOfClass("Tool")
                            if backpackTool then
                                backpackTool.Parent = char
                                tool = backpackTool
                                task.wait(0.1)
                            end
                        end

                        if not tool then return end

                        local hitList = {}
                        for _, p in pairs(Players:GetPlayers()) do
                            if p ~= LocalPlayer and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                                if hum and hum.Health > 0 then
                                    table.insert(hitList, {
                                        knockback = 50,
                                        isClosestEnemy = true,
                                        origin = p.Character.HumanoidRootPart.Position,
                                        enemyModel = p.Character,
                                        distance = 1,
                                        direction = Vector3.new(0, 1, 0)
                                    })
                                end
                            end
                        end

                        if #hitList > 0 then
                            Event:InvokeServer(
                                "AttemptWeaponHit",
                                {
                                    attackCycleData = {
                                        knockbackMul = 1, slowMult = 0.2, attackTime = 0.65, lungeMul = 1, slowTime = 1.5
                                    },
                                    knockback = 50,
                                    shouldLock = true,
                                    shouldLunge = true,
                                    hitboxOffset = Vector3.new(0, 0, 0),
                                    isCritical = true,
                                    shouldSlow = true,
                                    attackCooldown = 0,
                                    damage = 100,
                                    lungeKnockback = 55,
                                    cycleIndex = 1,
                                    slowMult = 0.2,
                                    hitboxSize = Vector3.new(50, 50, 50),
                                    weaponDefinition = {
                                        attackCycle = {
                                            ["1"] = {knockbackMul = 1, slowMult = 0.2, attackTime = 0.65, lungeMul = 1, slowTime = 1.5},
                                            ["2"] = {lungeMult = 1, slowMult = 0.2, attackTime = 0.65, knockbackMul = 1, slowTime = 1.5},
                                            ["3"] = {lungeMult = 0.75, slowMult = 0.2, attackTime = 0.71666666666667, knockbackMul = 1.5, slowTime = 1.5},
                                            ["4"] = {lungeMult = 2.25, attackTime = 0.98333333333333, slowMult = 0.2, hitboxOffsetAdd = Vector3.new(0, 0, -1.5), hitboxSizeAdd = Vector3.new(0, 0, 3), knockbackMul = 2.25, slowTime = 1.5}
                                        },
                                        attackOrder = {"1", "2", "3", "4"}
                                    },
                                    tool = tool,
                                    slowTime = 1.5
                                },
                                hitList
                            )
                        end
                    end)
                    task.wait(0.2)
                end
            end)
        end
    end
})

