   if not AimbotState.E then return end
   -- 检查是否按住右键
   if UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
    local target=getClosestPlayer()
    if target then aimAt(target) end
   end
  end)
  print("[自描] 已开启 (按住右键瞄准)")
 end)
 ABS:AddButton("○  关闭自描",function()
