  conn=RS.Stepped:Connect(function()
   t=t+0.1
   if not hrp or not hrp.Parent then conn:Disconnect() return end
   hrp.CFrame=hrp.CFrame*CFrame.Angles(0,0.1,0)
  end)
  task.delay(3,function() conn:Disconnect() print("[整活] 转圈结束") end)
